// src/server/vercelHandler.ts
var config = {
  api: {
    bodyParser: false
  }
};
var app = createAutoelectricApiApp();
function restoreRewrittenApiUrl(req) {
  const rawUrl = req.url || "/";
  try {
    const parsed = new URL(rawUrl, "http://localhost");
    const forwardedPath = parsed.searchParams.get("__vercel_path");
    if (forwardedPath !== null) {
      parsed.searchParams.delete("__vercel_path");
      const cleanSubPath = forwardedPath.replace(/^\/+/, "");
      const remainingQuery = parsed.searchParams.toString();
      req.url = `/api/${cleanSubPath}${remainingQuery ? `?${remainingQuery}` : ""}`;
    }
  } catch {
  }
}
function handler(req, res) {
  restoreRewrittenApiUrl(req);
  return new Promise((resolve, reject) => {
    const onDone = () => {
      res.off("finish", onDone);
      res.off("close", onDone);
      res.off("error", onErr);
      resolve();
    };
    const onErr = (err) => {
      res.off("finish", onDone);
      res.off("close", onDone);
      res.off("error", onErr);
      reject(err);
    };
    res.on("finish", onDone);
    res.on("close", onDone);
    res.on("error", onErr);
    app(req, res);
  });
}
export {
  config,
  handler as default
};
